import { LogOut } from "lucide-react";
import { useState } from "react";
import { globalSearch } from "@/services/search";

export default function Header() {
    const logout = async () => {
        await fetch("/api/auth/logout", {
            method: "POST",
            credentials: "include",
        });

        window.location.href = "/login";
    };

    const [query, setQuery] = useState("");
    const [results, setResults] = useState<any[]>([]);

    const search = async (q: string) => {
        setQuery(q);

        if (!q) return setResults([]);

        const data = await globalSearch(q);
        setResults(data);
    };

    return (
        <header className="h-16 border-b bg-white flex items-center justify-between px-6">
            <h2 className="text-lg font-semibold">
                Inventory Dashboard
            </h2>

            <div className="flex items-center gap-6">
                <div className="relative">
                    <input
                        value={query}
                        onChange={(e) => search(e.target.value)}
                        placeholder="Search products, orders..."
                        className="border rounded-lg px-4 py-1.5 w-64 text-sm focus:outline-none focus:ring-2 focus:ring-teal-500"
                    />
                    {results.length > 0 && (
                        <div className="absolute top-full left-0 bg-white border rounded-lg mt-2 w-full shadow-lg z-50 py-2">
                            {results.map((r, i) => (
                                <div key={i} className="px-4 py-2 hover:bg-gray-50 cursor-pointer">
                                    <p className="text-sm font-medium">{r.name || r.id}</p>
                                    <p className="text-xs text-gray-500">{r.sku || r.status}</p>
                                </div>
                            ))}
                        </div>
                    )}
                </div>

                <button
                    onClick={logout}
                    className="flex items-center gap-2 text-red-500 hover:text-red-600 font-medium text-sm"
                >
                    <LogOut size={18} />
                    Logout
                </button>
            </div>
        </header>
    );
}